Problem:
A water purification station has a large plant and a small plant. The large plant purifies 30 units of water per hour and produces 20 units of by-product per hour. The small plant purifies 12 units of water per hour and produces 2 units of by-product per hour. The large plant requires 15 filters while the small plant requires 12 filters per hour. The water purification station only has available 1200 filters right now. If the station must purify at least 1200 units of water and at least 500 units of by-product, how many hours should each plant be run to minimize the total time needed?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "large_plant_hours",
    "lower": 0.0,
    "upper": null,
    "integer": false
   },
   {
    "name": "small_plant_hours",
    "lower": 0.0,
    "upper": null,
    "integer": false
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "large_plant_hours",
     "coef": 1.0
    },
    {
     "var": "small_plant_hours",
     "coef": 1.0
    }
   ]
  },
  "constraints": [
   {
    "name": "water_purified",
    "terms": [
     {
      "var": "large_plant_hours",
      "coef": 30.0
     },
     {
      "var": "small_plant_hours",
      "coef": 12.0
     }
    ],
    "sense": ">=",
    "rhs": 1200.0
   },
   {
    "name": "by_product",
    "terms": [
     {
      "var": "large_plant_hours",
      "coef": 20.0
     },
     {
      "var": "small_plant_hours",
      "coef": 2.0
     }
    ],
    "sense": ">=",
    "rhs": 500.0
   },
   {
    "name": "filters_available",
    "terms": [
     {
      "var": "large_plant_hours",
      "coef": 15.0
     },
     {
      "var": "small_plant_hours",
      "coef": 12.0
     }
    ],
    "sense": "<=",
    "rhs": 1200.0
   }
  ]
 },
 "facts": {
  "objective": 40.0,
  "values": {
   "large_plant_hours": 40.0,
   "small_plant_hours": 0.0
  },
  "binding": [
   "water_purified"
  ],
  "slack": {
   "water_purified": 0.0,
   "by_product": 300.0,
   "filters_available": 600.0
  },
  "shadow_prices": {
   "water_purified": 0.033333,
   "by_product": 0.0,
   "filters_available": 0.0
  }
 }
}
